-- Study Abroad country content, BATCH 1: United Kingdom, United States, Canada, Australia, Germany.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('united-kingdom', 'united-states', 'canada', 'australia', 'germany'));
UPDATE countries SET why_title = 'Why study in the UK?', why_body = '<p>The UK combines globally ranked universities with short, intensive degrees. In the QS World University Rankings 2027, Imperial College London is joint 2nd, Oxford 4th and Cambridge 6th.</p><ul><li>Most taught Master''s degrees take 1 year, saving a year of tuition and living costs</li><li>Bachelor''s degrees are usually 3 years (4 with a placement or in Scotland)</li><li>Strong industry links, placements and a wide choice of subjects</li><li>Post-study work through the Graduate visa (see the visa section for the current length)</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Student visa</strong> (unless they already hold another right to study). You apply online once you hold a <strong>Confirmation of Acceptance for Studies (CAS)</strong> from a licensed sponsor university.</p><ul><li>Application fee: about £558 (raised in April 2026)</li><li>Immigration Health Surcharge: about £776 for each year of the visa, paid when you apply</li><li>Maintenance funds: about £1,529 a month in London or £1,171 a month elsewhere, for up to 9 months, held for 28 consecutive days</li><li>Documents: passport, CAS, financial evidence, English test result where required, TB test result for some countries, ATAS certificate for sensitive subjects</li><li>Graduate visa: currently 2 years (3 for PhD). For applications made from 1 January 2027 the standard length is planned to be 18 months, so check the latest rules</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official GOV.UK site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Undergraduate applications go through <strong>UCAS</strong> (up to 5 choices). Postgraduate applications are made directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>Personal statement (UCAS) or statement of purpose</li><li>1-2 references</li><li>CV for Master''s and MBA applications</li><li>Passport copy and proof of English proficiency</li><li>Portfolio or admissions test for some courses, for example Oxford and Cambridge admissions tests and interviews</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and course; living costs are highest in London. The Home Office funds figure (£1,171-£1,529 a month) is a good planning guide for living costs.</p><ul><li>Tuition (international): roughly £11,000-£40,000 a year for most courses; clinical and MBA courses cost more</li><li>Visa fee and health surcharge: about £558 plus £776 per year</li><li>Accommodation, food and transport: major monthly expense, higher in London</li><li>Part-time work: usually up to 20 hours a week in term time on a Student visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements differ by university, course and level.</p><ul><li><strong>Foundation / Pathway:</strong> completed secondary school, with English at roughly IELTS 4.5-5.5</li><li><strong>Bachelor''s:</strong> completed secondary education with strong grades; some universities accept Indian Class 12 results directly, others ask for a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, usually a 2:1 equivalent</li><li><strong>MBA:</strong> a degree plus typically 2-3 years of work experience</li><li>English: usually IELTS 6.0-7.0 overall, depending on the course (a UKVI-approved test for the visa)</li></ul>' WHERE slug = 'united-kingdom';
UPDATE countries SET why_title = 'Why study in the USA?', why_body = '<p>The US has the largest number of ranked universities in the world (184 in QS 2027); MIT is ranked 1st, Stanford joint 2nd, Harvard 5th and Caltech 7th. Flexible degrees let you explore before you specialise.</p><ul><li>Choose or change your major during the first two years at most universities</li><li>Strong research, internship and co-op opportunities</li><li>Post-study work through Optional Practical Training (OPT): 12 months, plus a 24-month STEM extension for eligible degrees</li><li>Large scholarship and assistantship funding, especially for Master''s and PhD students</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Most international students need an <strong>F-1 visa</strong>. After admission your university issues a <strong>Form I-20</strong>; you pay the SEVIS fee and attend a visa interview at a US embassy or consulate.</p><ul><li>Reported fees: SEVIS I-901 about $350 and visa application about $185. A new visa integrity fee (minimum $250) was legislated in 2025 and its implementation is still unclear</li><li>Documents: passport, I-20, DS-160 confirmation, financial evidence, academic records and test scores</li><li>Interview: show that you can pay for your studies and intend to study full time</li><li>Duration of status: a final rule effective 15 September 2026 gives new F-1 students an admission end date tied to their programme (maximum 4 years) and shortens the grace period after study from 60 to 30 days</li><li>OPT: a proposed rule (October 2026) to charge schools a fee per OPT recommendation is only a proposal and is not in force</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official US State Department site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most universities use the <strong>Common App</strong> or their own portal for undergraduate admission; graduate applications go to each programme.</p><ul><li>High school or university transcripts, and a grade evaluation (WES or similar) where requested</li><li>Essays or statement of purpose</li><li>2-3 letters of recommendation</li><li>SAT/ACT (optional at many universities); GRE/GMAT for some graduate programmes</li><li>Proof of English proficiency (TOEFL, IELTS, Duolingo)</li><li>Financial documents for the I-20, and application fees (often $50-$100)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs vary hugely between public and private universities and by state. Universities publish a "cost of attendance" that includes tuition, housing, food, books and insurance.</p><ul><li>Tuition: roughly $20,000-$60,000+ a year; private universities cost more than public</li><li>Housing and food: roughly $10,000-$20,000 a year depending on the city</li><li>Health insurance is usually mandatory and may be charged by the university</li><li>Work: on-campus jobs up to 20 hours a week in term time; off-campus work needs authorisation such as CPT or OPT</li><li>Some universities have added their own international student service fees from 2026</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Admission is competitive and holistic: grades matter, but so do essays, activities and recommendations.</p><ul><li><strong>Bachelor''s:</strong> 12 years of schooling (for example Class 12 for Indian students), strong grades, SAT/ACT where required</li><li><strong>Master''s:</strong> a 3-4 year bachelor''s degree; many programmes expect a strong GPA and some ask for GRE/GMAT</li><li><strong>MBA:</strong> a bachelor''s degree, work experience and GMAT/GRE for most programmes</li><li><strong>PhD:</strong> a relevant degree, research experience and recommendations</li><li>English: TOEFL iBT (often 80-100+) or IELTS 6.5-7.0, depending on the university</li></ul>' WHERE slug = 'united-states';
UPDATE countries SET why_title = 'Why study in Canada?', why_body = '<p>Canada offers high-quality, internationally recognised degrees in safe and multicultural cities. McGill ranks 30th in the QS World University Rankings 2027, the highest in Canada.</p><ul><li>Work off campus while you study, within the permitted hours</li><li>Post-Graduation Work Permit (PGWP) after eligible programmes</li><li>Co-op and internship options, especially at Waterloo and other technical universities</li><li>Tuition is often lower than in the US or UK</li></ul>', visa_title = 'Study permit requirements', visa_body = '<p>Most students need a <strong>study permit</strong>, plus a visitor visa or eTA depending on nationality. Canada also caps how many new permits are issued each year.</p><ul><li>Acceptance letter from a Designated Learning Institution (DLI)</li><li>Provincial or territorial attestation letter (PAL/TAL) for most applicants. From 1 January 2026, Master''s and PhD students at public universities are exempt</li><li>Proof of funds: CA$23,448 for living costs for a single applicant outside Quebec (from 1 September 2026), on top of tuition and travel</li><li>Passport, photos, and medical exam or police certificate where required</li><li>2026 cap: about 408,000 approved permits, of which about 155,000 are for new arrivals</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official IRCC site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply to each university or college directly (or through a provincial portal such as OUAC in Ontario), then apply for the study permit with your acceptance letter.</p><ul><li>Academic transcripts and certificates</li><li>English or French test score</li><li>Statement of purpose and references (usually for Master''s and PhD)</li><li>Resume or portfolio for some programmes</li><li>Passport copy</li><li>Quebec: a CAQ (Quebec acceptance certificate) is needed as well as the federal permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for international students is often lower than in the US or UK, but varies by province and programme. Use the IRCC figure for living costs as a minimum.</p><ul><li>Tuition: roughly CA$15,000-$40,000 a year for undergraduate programmes; professional Master''s can be higher</li><li>Living costs: IRCC requires CA$23,448 (single, outside Quebec); big cities like Toronto and Vancouver cost more</li><li>Health insurance: depends on the province; some universities charge their own plan</li><li>Application fees: about CA$100-$150 per university, plus the study permit fee</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Eligibility depends on the programme and institution.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with the required subjects</li><li><strong>Master''s:</strong> a 4-year bachelor''s degree, usually a B average or higher</li><li><strong>Colleges and diplomas:</strong> secondary school completion, plus a language test</li><li>English: IELTS Academic 6.0-7.0 or equivalent TOEFL/PTE; French programmes need TEF/TCF</li><li>PGWP: bachelor''s, master''s and doctoral graduates are not subject to the field-of-study list; check eligibility for diplomas</li></ul>' WHERE slug = 'canada';
UPDATE countries SET why_title = 'Why study in Australia?', why_body = '<p>Australia is home to the Group of Eight research universities and high-quality teaching in a safe, multicultural environment. UNSW Sydney is ranked 19th in the QS World University Rankings 2027, now the top Australian university.</p><ul><li>Work rights while studying (the fortnightly limit is set by the government)</li><li>Post-study work options through the Temporary Graduate visa (subclass 485)</li><li>Strong industry links in engineering, health, business and IT</li><li>Regional study can add extra post-study work time</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Student visa (subclass 500)</strong> and an offer and <strong>Confirmation of Enrolment (CoE)</strong> from a CRICOS-registered provider.</p><ul><li>Application fee: reported at AUD 2,500 for applications lodged from 1 July 2026 (earlier figures of AUD 1,600-2,000 are out of date)</li><li>Financial capacity: AUD 29,710 for 12 months of living costs for a single applicant, plus tuition and travel</li><li>Genuine Student requirement: a written statement showing why you chose Australia, the course and your plans</li><li>English test result, unless exempt</li><li>Overseas Student Health Cover (OSHC) for the whole visa period, with limited exceptions</li><li>Health examination and police clearance where required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Home Affairs site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university (or through an authorised agent) and then apply for the visa with your CoE.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency result</li><li>Statement of purpose, CV and references for postgraduate courses</li><li>Portfolio or work experience for some courses (for example MBA and design)</li><li>Passport copy and Genuine Student statement for the visa</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition varies by university and course; international fees are higher than for domestic students. Living costs vary, with Sydney and Melbourne the most expensive.</p><ul><li>Tuition: roughly AUD 25,000-$50,000 a year for most courses; medicine and some health courses cost more</li><li>Living costs: the visa requires AUD 29,710 for 12 months (single, 2026 figure)</li><li>Visa fee: AUD 2,500 (reported, from July 2026)</li><li>OSHC: required cover, typically a few hundred to over a thousand dollars a year</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Entry requirements depend on the university, level and course.</p><ul><li><strong>Foundation / Diploma:</strong> completed Year 11 or 12 (or equivalent) with the required grades</li><li><strong>Bachelor''s:</strong> completed secondary school (Year 12 or equivalent); some universities ask for specific subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a strong average; MBAs ask for work experience</li><li>English: IELTS 6.0-7.0 or equivalent TOEFL/PTE/C1 Advanced</li><li>Genuine Student: the visa officer will check your study history, finances and plan</li></ul>' WHERE slug = 'australia';
UPDATE countries SET why_title = 'Why study in Germany?', why_body = '<p>Germany offers world-class engineering and research with no tuition at most public universities, a strong industry base and a growing range of English-taught Master''s programmes.</p><ul><li>Most public universities do not charge tuition (Baden-Württemberg charges non-EU students; see the cost section)</li><li>Strong in engineering, computer science, natural sciences and business</li><li>Up to 18 months after graduation to look for a job</li><li>Strong industry links with firms such as Siemens, BMW and SAP</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students from outside the EU/EEA need a <strong>national visa (D) for study</strong>, applied for at the German embassy or consulate, and a residence permit after arrival.</p><ul><li>Admission letter (or conditional admission) from a German university</li><li>Proof of funds: €11,904 a year (€992 a month) in a blocked account (Sperrkonto), a scholarship, or a formal sponsor declaration</li><li>Health insurance valid in Germany</li><li>Passport, photos, CV and proof of academic qualifications</li><li>Language certificate: German (B2-C1) for German-taught courses or English proof for English-taught courses</li><li>Some countries (including India, China and Vietnam) need an APS certificate for academic verification</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official German embassy site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Many universities use <strong>uni-assist</strong> to check international applications; others have their own portals, or use <strong>hochschulstart</strong> for restricted subjects.</p><ul><li>Certified copies of school or university certificates and transcripts</li><li>Language certificate (German or English)</li><li>CV and motivation letter</li><li>APS certificate where required for your country</li><li>Letters of recommendation for some Master''s programmes</li><li>Application fee for uni-assist (usually €30-€75)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition-free public universities make Germany one of the most affordable destinations. You still pay semester fees and living costs.</p><ul><li>Tuition: free at most public universities. Baden-Württemberg charges non-EU students €1,500 per semester; some programmes and private universities charge more</li><li>Semester contribution: typically a few hundred euros per semester, often including a public transport ticket</li><li>Living costs: about €992 a month is the visa guide; Munich is more expensive than most other cities</li><li>Health insurance is mandatory for all students</li><li>Fee exemptions (for example for some scholarship holders) depend on the state, so check the rules of your university</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Entry requirements depend on the university and the level of study.</p><ul><li><strong>Bachelor''s:</strong> a recognised secondary school certificate; some applicants need to complete a Studienkolleg first</li><li><strong>Master''s:</strong> a recognised bachelor''s degree in a related field; many programmes ask for strong marks and sometimes GRE/GMAT</li><li><strong>Language:</strong> German (TestDaF, DSH, Goethe) for German-taught courses; IELTS 6.0-6.5 or TOEFL 80+ for English-taught courses</li><li>Subjects with limited places (NC) may select on grades</li></ul>' WHERE slug = 'germany';
COMMIT;
